import type {
    DiagramEdgeKind,
    DiagramFlowPreset,
    DiagramRole,
    DiagramType,
} from '../../../services/diagrams/diagram_data';
import type { DiagramCreationTool } from '../../../services/diagrams/diagram_edit_types';
import { MINDMAP_TOPIC_PLACEMENT, type DiagramNodePlacementDefinition } from '../../../services/diagrams/diagram_node_placement_service';
import { MINDMAP_ROOT_DIAMETER } from '../../../services/diagrams/diagram_layout';

export type DiagramCreationToolDefinition =
    | { category: 'edge', edgeKind: DiagramEdgeKind, label: string, tool: DiagramCreationTool }
    | { category: 'fragment', label: string, tool: 'fragment' }
    | { category: 'group', label: string, tool: 'group' }
    | { category: 'node', definition: DiagramNodePlacementDefinition, label: string, role: DiagramRole, tool: DiagramCreationTool };

const COMPONENT_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New component', role: 'focal', width: 160 },
    kind: 'component',
};
const ENTITY_PREVIEW_SIZE = { height: 48, width: 160 };
const ENTITY_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { fields: [], label: 'New entity', role: 'focal', width: ENTITY_PREVIEW_SIZE.width },
    kind: 'entity',
    previewSize: ENTITY_PREVIEW_SIZE,
};
const PARTICIPANT_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New participant', role: 'focal', width: 160 },
    kind: 'participant',
};
const STEP_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New step', role: 'focal', width: 160 },
    kind: 'step',
};
const DECISION_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 96, label: 'New decision', role: 'focal', width: 96 },
    kind: 'decision',
};
const STATE_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New state', role: 'focal', width: 160 },
    kind: 'state',
};
const MINDMAP_ROOT_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: MINDMAP_ROOT_DIAMETER, label: 'New root', role: 'focal', width: MINDMAP_ROOT_DIAMETER },
    kind: 'root',
};
const FLOWCHART_TERMINAL_SIZE = { height: 48, width: 120 };
const STATE_TERMINAL_SIZE = { height: 24, width: 24 };

function terminalDefinition(kind: 'end' | 'start', preset: DiagramFlowPreset): DiagramNodePlacementDefinition {
    const { height, width } = preset === 'state' ? STATE_TERMINAL_SIZE : FLOWCHART_TERMINAL_SIZE;
    const label = kind === 'start' ? 'Start' : 'End';

    return { defaults: { height, label, role: 'focal', width }, kind };
}

function nodeTool(label: string, definition: DiagramNodePlacementDefinition): DiagramCreationToolDefinition {
    return { category: 'node', definition, label, role: definition.defaults.role, tool: `node:${definition.kind}` };
}

function edgeTool(label: string, edgeKind: DiagramEdgeKind): DiagramCreationToolDefinition {
    return { category: 'edge', edgeKind, label, tool: `edge:${edgeKind}` };
}

/** Returns creation tools permitted by active diagram schema, in menu order. */
export function diagramCreationTools(
    type: DiagramType,
    preset: DiagramFlowPreset | null,
    hasMindmapRoot = false,
): readonly DiagramCreationToolDefinition[] {
    const common: DiagramCreationToolDefinition[] = [{ category: 'group', label: 'Group', tool: 'group' }];
    if (type === 'architecture') {
        return [
            nodeTool('Component', COMPONENT_DEFINITION),
            edgeTool('Connection', 'connection'),
            edgeTool('Data', 'data'),
            edgeTool('Async', 'async'),
            ...common,
        ];
    }
    if (type === 'dependency') {
        return [
            nodeTool('Component', COMPONENT_DEFINITION),
            edgeTool('Dependency', 'dependency'),
            edgeTool('Cycle', 'cycle'),
            ...common,
        ];
    }
    if (type === 'entity') {
        return [nodeTool('Entity', ENTITY_DEFINITION), edgeTool('Relationship', 'relationship'), ...common];
    }
    if (type === 'sequence') {
        return [
            nodeTool('Participant', PARTICIPANT_DEFINITION),
            edgeTool('Call', 'call'),
            edgeTool('Return', 'return'),
            edgeTool('Async', 'async'),
            edgeTool('Success', 'success'),
            ...common,
            { category: 'fragment', label: 'Fragment', tool: 'fragment' },
        ];
    }
    if (type === 'mindmap') {
        return hasMindmapRoot
            ? [nodeTool('Topic', MINDMAP_TOPIC_PLACEMENT), edgeTool('Connection', 'connection'), ...common]
            : [nodeTool('Root', MINDMAP_ROOT_DEFINITION), ...common];
    }
    if (!preset) throw new Error('Flow diagram creation tools require a preset');

    const terminalTools = [
        nodeTool('Start', terminalDefinition('start', preset)),
        nodeTool('End', terminalDefinition('end', preset)),
    ];
    if (preset === 'state') {
        return [...terminalTools, nodeTool('State', STATE_DEFINITION), edgeTool('Transition', 'transition'), ...common];
    }

    return [
        ...terminalTools,
        nodeTool('Step', STEP_DEFINITION),
        nodeTool('Decision', DECISION_DEFINITION),
        edgeTool('Flow', 'flow'),
        ...common,
    ];
}

import { memo } from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramNode } from '../../../services/diagrams/diagram_layout'
import {
    diagramSelectionService, type DiagramSelectionService,
} from '../../../services/diagrams/diagram_selection_service'
import { DiagramNode } from '../rendering/diagram_node'
import {
    diagramObjectDetailsService, type DiagramObjectDetailsService,
} from '../details/diagram_object_details_service'
import { useDiagramNodeGeometryField } from './use_diagram_geometry'
import { useIsDiagramObjectSelected } from './use_diagram_selection'
import { useEditableDiagramMetadataField, useEditableDiagramNodeField } from './use_editable_diagram'
import { diagramEmphasisService, type DiagramEmphasisService } from '../../../services/diagrams/diagram_emphasis_service'
import { useDiagramObjectDimmed } from '../surface/use_diagram_emphasis'

interface EditableDiagramNodeProps {
    details?: DiagramObjectDetailsService
    emphasis?: DiagramEmphasisService
    geometry?: DiagramGeometryService
    nodeId: string
    selection?: DiagramSelectionService
    session?: DiagramEditSessionService
}

/**
 * One node of the New diagram. Every value it renders arrives through its own field subscription, so an edit to a
 * sibling node, an edge, a group, or the metadata cannot rerender this leaf.
 */
function EditableDiagramNodeLeaf({
    details = diagramObjectDetailsService,
    emphasis = diagramEmphasisService,
    geometry = diagramGeometryService,
    nodeId,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: EditableDiagramNodeProps) {
    const diagramType = useEditableDiagramMetadataField('type', session)
    const preset = useEditableDiagramMetadataField('preset', session)
    const kind = useEditableDiagramNodeField(nodeId, 'kind', session)
    const label = useEditableDiagramNodeField(nodeId, 'label', session)
    const role = useEditableDiagramNodeField(nodeId, 'role', session)
    const sublabel = useEditableDiagramNodeField(nodeId, 'sublabel', session)
    const tag = useEditableDiagramNodeField(nodeId, 'tag', session)
    const fanIn = useDiagramNodeGeometryField(nodeId, 'fanIn', geometry)
    const height = useDiagramNodeGeometryField(nodeId, 'height', geometry)
    const width = useDiagramNodeGeometryField(nodeId, 'width', geometry)
    const x = useDiagramNodeGeometryField(nodeId, 'x', geometry)
    const y = useDiagramNodeGeometryField(nodeId, 'y', geometry)
    const selected = useIsDiagramObjectSelected(nodeId, 'node', selection)
    const dimmed = useDiagramObjectDimmed('new', 'node', nodeId, emphasis)
    if (!diagramType || label === null || role === null || width === null || height === null) return null

    const handleSelect = (_selection: unknown, ctrlKey: boolean) => {
        if (session.getActiveToolSnapshot() !== 'select') return

        const identity = { objectId: nodeId, objectKind: 'node' } as const
        if (ctrlKey) {
            selection.toggle(identity)
        } else {
            selection.replace([identity])
        }
        const sessionSnapshot = session.getSessionSnapshot()
        if (sessionSnapshot) emphasis.moveTargetIfActive({diagramId: sessionSnapshot.sourceDiagramId, objectId: nodeId, objectKind: 'node', surface: 'new'})
    }
    const handleOpenDetails = () => details.open({ objectId: nodeId, objectKind: 'node' })

    const node: PositionedDiagramNode = {
        fanIn: fanIn ?? 0,
        height,
        id: nodeId,
        label,
        role,
        width,
        x: x ?? 0,
        y: y ?? 0,
        ...(kind ? { kind } : {}),
        ...(sublabel ? { sublabel } : {}),
        ...(tag ? { tag } : {}),
    }

    return (
        <DiagramNode
            circular={diagramType === 'mindmap'}
            diagramType={diagramType}
            dimmed={dimmed}
            editableLabel={{ session }}
            entityFieldSource={diagramType === 'entity' ? { nodeId, session } : undefined}
            flowPreset={preset ?? undefined}
            formattingStore={session}
            node={node}
            onOpenDetails={handleOpenDetails}
            onSelect={handleSelect}
            selected={selected}
        />
    )
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramNode = memo(EditableDiagramNodeLeaf)

